def comps(g,v):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==v and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<h and 0<=b<w and g[a][b]==v and (a,b) not in seen: st.append((a,b))
                out.append(comp)
    return out
