def f(g,maxgap=4):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]; bg=g[0][0]
    objs={(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg}
    r0=min(r for r,c in objs); r1=max(r for r,c in objs); c0=min(c for r,c in objs); c1=max(c for r,c in objs)
    # 1) frame fill
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r in(r0,r1) or c in(c0,c1)) and g[r][c]==bg: out[r][c]=2
    # 2) sandwich runs between two objects, len<=maxgap (rows & cols)
    for r in range(h):
        c=0
        while c<w:
            if g[r][c]==bg:
                s=c
                while c<w and g[r][c]==bg: c+=1
                if s>0 and c<w and g[r][s-1]!=bg and g[r][c-1]!=bg and c-s<=maxgap:
                    for k in range(s,c): out[r][k]=2
            else: c+=1
    for col in range(w):
        r=0
        while r<h:
            if g[r][col]==bg:
                s=r
                while r<h and g[r][col]==bg: r+=1
                if s>0 and r<h and g[s-1][col]!=bg and g[r-1][col]!=bg and r-s<=maxgap:
                    for k in range(s,r): out[k][col]=2
            else: r+=1
    # 3) trailing/leading gap to bbox edge (len<=maxgap)
    for r in range(h):
        # find objects in row within [c0,c1]
        oc=[c for c in range(c0,c1+1) if g[r][c]!=bg]
        if oc:
            lo,hi=oc[0],oc[-1]
            if hi<c1:
                for c in range(hi+1,c1+1):
                    if g[r][c]==bg and c-hi<=maxgap: out[r][c]=2
            if lo>c0:
                for c in range(c0,lo):
                    if g[r][c]==bg and lo-c-1<=maxgap: out[r][c]=2
    return out
