def fsand(g,maxg=4):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]; bg=g[0][0]
    objs={(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg}
    r0=min(r for r,c in objs); r1=max(r for r,c in objs); c0=min(c for r,c in objs); c1=max(c for r,c in objs)
    # horizontal: gap strictly between two objects, len<=maxg
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]!=bg]
        for a,b in zip(cs,cs[1:]):
            for k in range(a+1,b):
                if b-a-1<=maxg: out[r][k]=2
    return out
