    r0=min(r for r,c in objs); r1=max(r for r,c in objs); c0=min(c for r,c in objs); c1=max(c for r,c in objs)
    def iso(rr,cc):
        return not any(0<=rr+dr<h and 0<=cc+dc<w and i[rr+dr][cc+dc]!=i[rr][cc] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
    res=[]
    for r in range(h):
        oc=[c for c in range(w) if i[r][c]!=bg]
        for a,b in zip(oc,oc[1:]):
            ll=b-a-1
            if ll<=0: continue
            onf=r in(r0,r1)
            res.append(('H',r,a,b,ll,onf,'I' if (iso(r,a) and iso(r,b)) else 'N','F' if o[r][a+1]==2 else 'S'))
